2>What changed recently</h2></div><a href="<?=url('/updates')?>">Full feed →</a></div><div class="feed"><?php foreach($updates as $u):?><a class="feed-row" href="<?=url('/game/'.e($u['slug']))?>"><div><small><?=e($u['game_name'])?> · <?=date('j M Y',strtotime($u['published_at']))?></small><h3><?=e($u['title'])?></h3></div><span class="verified"><?=((int)$u['verified']?'VERIFIED':'EDITORIAL')?></span></a><?php endforeach;?></div></section>